import pathlib,json,subprocess,statistics,hashlib,datetime,os
root=pathlib.Path('/media/mark/data/work/carve-quality-measurements-2026-10-02/deep-review')
session=json.load(open(root/'final-session.json')); rows=[]; cases=[('group',1024,'false'),('group',8192,'false'),('plain',128,'false'),('plain',1024,'false'),('plain',1024,'true')]
for round in range(8):
 for kind,n,positions in cases:
  source=('['+'; '.join(['@a']*n)+']\n') if kind=='group' else 'A paragraph with *emphasis*.\n\n'*n
  fixture=root/'rust-control-fixture.txt';fixture.write_text(source)
  for variant in (['main','candidate'] if round%2==0 else ['candidate','main']):
   start=datetime.datetime.now(datetime.timezone.utc).isoformat();load=os.getloadavg()
   raw=subprocess.check_output(['taskset','-c','6',str(root/'bin'/('rust-'+variant)),str(fixture),'401',positions],text=True)
   times,ast=raw.split('\n',1);r={'kind':kind,'n':n,'positions':positions,'variant':variant,'round':round,'samples':[float(v) for v in times.split(',')],'hash':hashlib.sha256(ast.encode()).hexdigest(),'observed_at':start,'load':load};rows.append(r)
 summary=[]
 for k,n,p in cases:
  both={v:[r for r in rows if (r['kind'],r['n'],r['positions'],r['variant'])==(k,n,p,v)] for v in ['main','candidate']}
  hashes={r['hash'] for rs in both.values() for r in rs}
  if len(hashes)!=1:raise RuntimeError('Output mismatch')
  med={v:statistics.median([x for r in rs for x in r['samples']]) for v,rs in both.items()}
  summary.append({'kind':k,'n':n,'positions':p,'main_ms':med['main'],'candidate_ms':med['candidate'],'change_percent':100*(med['candidate']/med['main']-1),'round_medians':{v:[statistics.median(r['samples']) for r in rs] for v,rs in both.items()}})
 (root/'rust-controls.json').write_text(json.dumps({'source_session':'final-session.json','binary_hashes':session['rust_binary_hashes'],'rounds_complete':round+1,'samples_per_round':401,'rows':rows,'summary':summary},indent=2)+'\n')
 print('Completed control round',round+1,flush=True)
print(json.dumps(summary,indent=2))
